import sys,re,glob,os
def snappy_raw(d):
    i=0;n=0;s=0
    while True:
        b=d[i];i+=1;n|=(b&0x7f)<<s;s+=7
        if b<0x80:break
    out=bytearray()
    while i<len(d):
        t=d[i];i+=1;k=t&3
        if k==0:
            l=t>>2
            if l>=60:
                nb=l-59;l=int.from_bytes(d[i:i+nb],'little');i+=nb
            l+=1;out+=d[i:i+l];i+=l;continue
        if k==1:
            l=((t>>2)&7)+4;o=((t>>5)<<8)|d[i];i+=1
        elif k==2:
            l=(t>>2)+1;o=int.from_bytes(d[i:i+2],'little');i+=2
        else:
            l=(t>>2)+1;o=int.from_bytes(d[i:i+4],'little');i+=4
        for _ in range(l):out.append(out[-o])
    return bytes(out)
def iwa(p):
    d=open(p,'rb').read();i=0;out=b''
    while i<len(d):
        l=int.from_bytes(d[i+1:i+4],'little');out+=snappy_raw(d[i+4:i+4+l]);i+=4+l
    return out
def strings(b):
    return [m.decode('utf-8','ignore') for m in re.findall(rb'[\x20-\x7e\xc2-\xf4\x80-\xbf\n\t]{4,}',b)]
for p in sys.argv[1:]:
    print('=====',os.path.basename(p))
    for s in strings(iwa(p)):
        s=s.strip()
        if len(s)>=4: print(s)
